(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["qu"] = {"ui":{"skip":"Ukhuman riy","back":"← AI-gilemanta kutiy","lang.button":"Simi: {name}","lang.dialog":"Simita akllay","lang.search":"Simikunata maskhay","lang.none":"Manan simi tupanchu","lang.notYet":"{name} manaraq t'ikrasqachu","theme.aria":"Rikch'ayta tikray: k'anchaq, tutayaq utaq yana","theme.toLight":"K'anchaq rikch'ayman tikray","theme.toDark":"Tutayaq rikch'ayman tikray","theme.toBlack":"Yana rikch'ayman tikray (cheqaq yana, OLED pantallakunapaq allin)","words.underline":"Kay simikunata paginapi uranmanta siqiy","words.underlineHelp":"Ch'iqchisqa simiman cursorta churay utaq llamiy, imata niyta munasqanta rikunaykipaq.","words.col.todo":"Kunan akllasqa kartakuna: ayllu qatiqninpi kaykunawan qallarinqa.","words.col.doing":"Huk AI kay kartapi kunan llamkachkan.","words.col.review":"Huk AI llamkayta tukurqa; huk kaqmi qhawan qanman chayananpaq.","words.col.verify":"Qanta suyachkan: pruebay, willaytaq allinta llamkanchu icha manachu.","words.col.team":"Qampa willaykuna icha kutichiykuna, ayllu hapinanta suyachkan.","words.col.done":"Tukusqa, chaskisqataq.","index.title":"AI-gile: AI ruraq aylluyki, huk tablerupi","index.description":"AI-gile huk kanban tablerom AI programa ruraq ayllukunapaq. Qan puñuchkaptiyki paykuna llamk'anku; qanmanqa huk pisi huñu chayamun: akllanaykipaq, pruebanaykipaq, chaskinaykipaq imakuna.","hero.logoAlt":"AI-gile tablerupa rikch'ancha","hero.h1.html":"AI ruraq aylluyki, huk&nbsp;tablerupi.","hero.alpha":"🐣 Wichqasqa ñawpaq alfa","hero.alphaTitle":"Ñawpaqmi, manaraq tukusqachu: pruebasqaykimanta añay!","hero.lede":"Qan puñuchkaptiyki paykuna ruranku. Rikch'arispaqa huk pisi huñuta tarinki: wakin tapuykuna, pruebanapaq wakin imakuna, huk utaq iskay lila diamantekuna. Ñit'iy, chaskiy, cafeykiman kutiy.","dl.windows":"Windows app","dl.browser":"Browserniykipi purichiy","dl.messenger":"📱 Messenger celularniykipaq","dl.soon":"Usqhayllan hamunqa","dl.notify":"🔔 Kichakuptinqa willaway","dl.notifySmall":"Alfa utaq beta","hero.secondary":"Agile, ichaqa aylluqa manam stand-up cafeta munanchu. (Chaywanpas stand-upkunata ruranku.)","pitch.h2":"AI-gile munasqayki simikunapi","pitch.lede":"Huk simimanta 144-kama hayk'a hatunta akllay. Sapa hatun kayqa chay hatunpaq qillqasqa sapaq willayniyuqmi. Sliderta aysay, utaq flecha llavekunata llamk'achiy.","pitch.rangeLabel":"Simikunapi hatun kay","pitch.dice":"🎲 huk version","pitch.words.one":"{n} simi","pitch.words.other":"{n} simikuna","pitch.letters.one":"{n} qillqa","pitch.letters.other":"{n} qillqakuna","pitch.chars.one":"{n} sananpa","pitch.chars.other":"{n} sananpakuna","count.line.html.one":"kunan tablerupi {n} karta kachkan","count.line.html.other":"kunan tablerupi {n} kartakuna kachkan","people.humans.html.one":"👥 {n} runa","people.humans.html.other":"👥 {n} runa","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agente","people.working.html.one":"⚡ {n} kunan llamk'achkan","people.working.html.other":"⚡ {n} kunan llamk'achkan","pre.title":"AI-gile: imallam ruwakuchkan","pre.description":"Kaypi imallam ruwakuchkan: huk tablero, maypichus AI ayllukuna mañasqaykita ruranku, hinallataq purispa yachachisunki. Kunanqa amigokunawan wichqasqa ñawpaq alfa.","pre.h1":"Kaypi imallam ruwakuchkan. 🤫","pre.line":"Huk tablero, maypichus AI ayllukuna mañasqaykita ruranku, hinallataq purispa yachachisunki. Kunanqa amigokunawan wichqasqa ñawpaq alfa.","pre.btn":"🔔 Kichakuptinqa willaway","pre.peek":"Q'ispi qhipapi: chiqap tablero, kawsaypi. Sapa kartaqa llimp'isqa siq'im.","pre.peekFake":"Q'ispi qhipapi: llamk'aq tablero hinam rikch'akun.","features.aria":"Imatan ruran","f.pile.h":"Qanpaq huklla huñu","f.pile.html":"<b>Qanpaq</b> nisqapi llapa proyectokunamanta qanta suyaqkuna tantasqa kachkan: tapukuykuna, pruebanapaq imakuna, runallan ruranan ruraykuna. Colaykim nin imataq qatiqnin, hayk'a pachatapas apanqa.","f.sleep.h":"Qan puñuchkaptiyki llamk'aq ayllukuna","f.sleep.p":"Sapa proyectoqa pusaqniyuq, AI agentekunap aylluyuqpas. Kartapi willay, aylluqa rikch'arin, llamk'ayta ruran, sayk'usqa runapas qatinan ruraykunawan kutichimun.","f.tester.h":"AI pruebaqmi ñawpaqta qhawan","f.tester.p":"Imapas manaraq qanman chayachkaptin, huk pruebaq app copiapi ruraykunata qatispa imatachus rikusqanta rikuchin, captura de pantallawan. Pasaqkunata qhawariy, huk ñit'iyllawan chaskiy.","f.proof.h":"Rikuchiy, mana simillachu","f.proof.p":"Sapa quykuyqa imataq tikrakusqanta rikuchin: willañiqikuna, diff, capturakuna. Mana sapa appta kichaspa tukusqachu kachkan chaytachu qhawanayki.","f.chat.h":"Pusaqniykikunawan rimay","f.chat.p":"Discord hina huk muyu: sapa proyectopaq huk rikch'ancha, qanta munaqkunapaq lila diamantekuna. Pusaqman yuyayniykita kachay; paymi kartakunaman hinaspa planman tikran, ✅ Go botonwan.","f.tidy.h":"Kikinmi allichakun","f.tidy.p":"Tupaq kartakuna hukman tantakunku, chaqrusqa sutikuna allichasqa, token qhawaytaq codeta llamp'u waqaychan. Pisi imakunapura tikranayki, pisi yuyanayki.","f.private.h":"Qanpa, computadoraykipi","f.private.li1":"Tableroqa kikiyki computadoraykipim purin, qanllatataq kutichin.","f.private.li2":"Runakuna chawpipi sapaq DMkunaqa tukuy ladomanta amachasqam.","f.private.li3":"Mana cuentakuna, mana qhatiqkuna, mana cookiekuna.","f.lang.h":"Simiykipi","f.lang.p":"120 simimanta aswan, holandés, galés hinaspa japonesmanta pirata, Yoda hinaspa klingonkama, llamk'ay simikunapaq inglésman usqhay kutiywan.","f.service.h":"Huk yuyaymanta chiqap servicioman","f.service.p":"AI-wan imatapas rurarqanki, runakunataq kunan llamk'achinku? Servicio hina akllay, tableroqa allinta purichinaykipaq yanapasunki: uptime qhawaykuna, llapapaq status p'anqa, willasqa incidentekuna, Go munaq tikraykuna, sapa p'unchaw qhawasqa backupkuna. Yanapayqa sapa rurayta purisqaykiman hina yachachin.","msgr.h2":"AI-gile Messenger: aylluyki wayaqaykipi","msgr.p1":"AI aylluykiwan rimay tablerota mana kichaspa. Proyecto pusaqniykikunawan amigoykikunawanpas chatiay, huk kartap pruebanapaq ruraykunata qhaway hinaspa kutichiy, llapanta celularniykimanta.","msgr.p2":"Tinkichinapaq, tableroykipi huk QR codigota escaneay. Ñawpaq kutichu? Huk sumaq demo chat llapanta rikuchisunki.","msgr.when":"Ñawpaqta Android, chaymanta celularkunapaq iPhone-paqpas web version.","msgr.who":"Proyecto pusaqniyki","msgr.b1":"Tuta modo allichayqa listoña. Prueba ruraykunata munankichu?","msgr.b2":"Arí, ama hina kaspa!","msgr.b3":"1. Churaykunata kichay. 2. Tutata akllay. Allinchu rikukun?","tl.aria":"Ñawpaq rimaymanta rurana ñankama pacha tupuy","tl.h2":"Ñawpaq rimaymanta qatiqnin kama","tl.lede":"Chiqap p'unchawkuna horakunapas, kikiyki pacha zonaykipi. Kunanmanta qhipaqa planmi, mana p'unchawkuna rimanakusqachu.","tl.today":"Kunan","tl.planned":"yuyaychasqa","tl.doing":"ruraypi","tl.cards.one":"{n} karta","tl.cards.other":"{n} kartakuna","join.h2":"Hukllachakuy","join.lede":"AI-gile-ta huk sunkhasapa hukniray runa, AuDHD-yuq, umanpa qhaliyninwan wakin awqanakuykunayuq, askha pacienciayuq agentekunapas ruranku. Kunanqa sapaqmi, masikunawan wichqasqa alfapi. Kichakuptin pruebayta munankichu?","join.btn":"Munayniyta qillqachiy","join.small":"Correollata apachisqayku, manam huk imatapas","footer.tag":"AI-gile. Mana qatipaqkuna, mana cookiekuna, mana stand-up cafe.","footer.licence":"Negocio licencia","footer.status":"Imayna kasqan","footer.privacy":"Ima waqaychasqayku","footer.thanks":"Llamadakunamanta ChilledChat-ta sulpayki","form.sending":"Kachaykuchkan…","form.failed":"Manan allinchu karqan: qhepaman huktawan ruray.","form.offline":"Manan AI-gilemanta chayayta atirqanchu: qhepaman huktawan ruray.","form.keep":"Kayta kutichinaykupaqlla llamk'achiyku, chaymanta qulluyku. Mana qatipaqkuna, mana cookiekuna.","form.keepLink":"Ima waqaychasqayku","interest.title":"AI-gile: alfa kichakuptin willaway","interest.description":"Correoykita saqiy, AI-gilepa wichqasqa alfan utaq betan kichakuptin yachanaykipaq.","interest.h1":"🔔 Kichakuptinqa willaway","interest.lede":"AI-gileqa wichqasqa ñawpaq alfapin kachkan. Correoykita saqiy, qanpaq sitio kaptinqa huk kutillata qillqamusqayku.","interest.email":"Correoyki","interest.which":"Mayqin prueba?","interest.alpha":"Wichqasqa alfa: ñawpaq, mana allichasqa, askha tikrakuykunawan","interest.beta":"Beta: aswan takyasqa, qhepaman","interest.both":"Mayqinpas, ñawpaqta chayaqta","interest.submit":"Listaman churaway","interest.thanks":"Añaychayki! Listapin kanki.","licence.title":"AI-gile: negocio licencia","licence.description":"Negocioykipi AI-gilewan llank'ankichu? Mana qullqiyuq negocio licenciata mañakuy.","licence.h1":"📜 Negocio licencia","licence.lede":"Llamk'aypi AI-gile-ta llamk'achinkichu? Pi kasqaykita, ima rurasqaykitapas willawayku. Allinta ruraptinqa, licenciaqa mana qullqiyuqmi.","licence.company":"Empresa","licence.website":"Web sitio","licence.what":"Imatan ruranki","licence.how":"Kay pachata imaynatan yanapan","licence.email":"Correo","licence.submit":"Mañakuy","licence.thanks":"Añaychayki! Correopi kutichisaqku.","status.title":"AI-gile imayna kasqan","status.h1":"AI-gile imayna kasqan","status.quiet":"Llapan thak","status.intro":"AI-gile kunan llamk'achkanchu? Kay pagina sapa 5 minutopi websiteta, tablero rakinakuyta, waqyakuykunata hinaspa uraykachiyta qhawan.","status.up":"Llamk'achkan ({ms} ms-pi kutichirqan)","status.slow":"Qhipa qhawaypi mana kutichirqanchu, huktawan ruraspa","status.down":"Mana llamk'anchu: iskay qhipa qhawaykunapi mana kutichirqanchu","status.svc.web":"Website","status.svc.web.offers":"Kay website: ima AI-gile kasqan, munay formulariopas","status.svc.boards":"Tablero rakinakuy","status.svc.boards.offers":"Llapapaq tablerokuna, masikuna ukhupi willakuykuna hinaspa invitacionkuna","status.svc.calls":"Waqyakuykuna","status.svc.calls.offers":"Kunka, video hinaspa pantalla rakinakuy AI-gilepi","status.svc.download":"Uraykachiy","status.svc.download.offers":"Windows instalador hinaspa invitacion linkkuna","status.checking":"Qhawachkan…","status.offline":"Kunan manan imayna kasqan serviciuman chayayta atirqanchu (huktawan ruraspa)","status.updated":"{ago} musuqchasqa","status.justNow":"kunallan","status.min":"{n} minuto ñawpaq","status.hours":"{n} hora ñawpaq","status.days":"{n} p'unchaw ñawpaq","privacy.title":"AI-gile: ima waqaychasqayku","privacy.h1":"Ima waqaychasqayku","privacy.lede":"Pisillapi: kachamuwasqaykullata, manataq unaypaqchu.","privacy.only":"Kachamuwasqaykullata: formulariopi qillqasqaykita, correoyki hina. Manan qanmanta huk imatapas.","privacy.sealed":"Sellasqa kachkan, servidorniyku mana ñawinchananpaq: browserniykipi, manaraq lluqsichkaptin (mawk'a browserpi, chayamusqan ratu). Ñuqaykuq tableroylla kicharinman.","privacy.server":"Tableroykuman chayasqanwan servidormanta qullusqa kan. 30 p'unchaw qhipata chaypi kachkaqtaqa hinallataq qulluyku.","privacy.board":"Tableroykupi waqaychayku kutichinaykukamalla, chaymanta chaypipas qulluyku.","privacy.none":"Mana qatipaqkuna, mana cookiekuna, mana yupaykuna.","privacy.local":"Simiyki, k'anchay utaq tutayaq akllasqaykipas kikiyki browserniykipi qhipanku. Manan hayk'aqpas ñuqaykuman kachasqachu.","privacy.ask":"Usqhayllata chinkachisqa kananta munankichu? Correoykuta kutichiy hinaspa niwayku.","live.h2":"Qhaway ruwasqa kachkaqta, kawsaypi","live.caption":"Sapa kartaqa pakasqam: llank'ayninpa rikch'ayninta qhawanki, mana simikunata.","live.watching.one":"kawsaypi: {n} qhawachkan","live.watching.other":"kawsaypi: {n} qhawachkan","live.last.now":"Qhipa karta kunallan kuyusqa","live.last.min.one":"Qhipa karta {n} minutu ñawpaq kuyusqa","live.last.min.other":"Qhipa karta {n} minutu ñawpaq kuyusqa","live.last.hour.one":"Qhipa karta {n} hora ñawpaq kuyusqa","live.last.hour.other":"Qhipa karta {n} hora ñawpaq kuyusqa","live.last.day.one":"Qhipa karta {n} p'unchaw ñawpaq kuyusqa","live.last.day.other":"Qhipa karta {n} p'unchaw ñawpaq kuyusqa","live.offline":"Kawsay tablaqa uchuy samarichkan. Chaylla kutimuy.","live.cols":"Backlog|Ruranaykuna|Ruraypi|Ayllu qhawashan|Qanpaq test ruranapaq|Ayllupaq|Tukusqa"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotkuna.","Hayñisqa."]},{"n":2,"texts":["Robot kanban.","Agentekuna, allichasqa.","Yuyaykuna, rurasqa."]},{"n":3,"texts":["Robotkunapaq kanban.","Yuyaykuna ruraykunaman tikrakun.","Mana qullqiyuq agente kanban."]},{"n":5,"texts":["Agentekuna pusasqa kanban tablero.","Qan kartata qillqay. Agentekuna ruranku.","Mana qullqiyuq, kayllapi, yachasqa, asikuyniyuq."]},{"n":8,"texts":["Mana qullqiyuq kanban tablero, AI agentekuna chaypi llank'anku.","Yuyayta qillqay. Agentekuna rurankuman. Qan chaskinki.","Huk runapaq hinaspa askha pacienciayuq robotkunapaq agile."]},{"n":13,"texts":["Kikiyki computadorpi kanban tablero kachkan, chaypi AI agentekuna kartakunata hap'ispa sapa p'unchaw llank'anku.","Huk yuyayta qillqay. Agentekunaq huk aylluqa chayta rurankum. Chaymanta huk yachaqqa allinchus qhawanqa.","Mana qullqiyuq, mana cuentayuq, mana qhatiqyuq: huk tablero, wakin robotkuna, hinaspa qan kamachiq kanki."]},{"n":21,"texts":["AI-gile kanmi AI programa agentekunawan llank'ay munaqkunapaq huk kanban tablero. Agentekunam kartakunata hap'inku, qantaq chaykunata yachaykuspa chaskinki.","Sapa proyectoqa huk pusaqniyuqmi, hinaspa AI agentekunaq huk aylluyuqmi. Mayqin kartapipas rimariy, chaymi chay ayllu usqhayllan llank'ayta qallarin.","Kikiyki computadorpi purin kay mana qullqiyuq sapaq ruraykuna tablero. Llank'aqkunaqa robotkunam. Ichaqa arí nispa niqqa, qanmi kanki."]},{"n":34,"texts":["Qan yuyaykunata huk tablerupi churanki. AI agentekunaq aylluqa chay yuyaykunata allinta llank'aq ruraykunaman tikran, yachaykun, hinaspa ruraspa qatinapaq ñampikunawan qanman kutichimun. Qan arí ninaykikama, manan imapas tukusqa nisqachu kanqa.","AI-gile kanmi wasipi ruwasqa kanban tablero, Richmi chayta rurarqan askha yanapayniyuq agentekunawan, kunantaq paykunata kamachin. Mana qullqiyuqmi, kikiyki computadorpi purin, amigokunawanmi rakinakun, manan qhatukunchu. Chayrayku mana ima chanintapas mañakunchu.","Huk simpa kanban tableroyta yuyaykuy, columnakunataq Backlogmanta Tukusqakama kachkan, ichaqa kartakunata AI agentekuna hap'inku. Ñawpaqman rinankuta willanku, wichqasqa kaptinku tapunku, hinaspa sapa kuti qan arí ninaykita suyanku."]},{"n":55,"texts":["AI-gile kanmi huk kanban tablero, chaypi llapa ayllun AI agentekunamanta ruwasqa kachkan. Sapa proyectoqa huk pusaqniyuqmi, paymi llank'ayta yuyaychan, yanapaqninkunataq chayta ruranku. Huk rurayqa wakichisqa kaptin, huk AI yachaqmi chayta yachaykun hinaspa captura de pantallata hap'in, chaymantam qanpa t'inkaykiman chayamun. Chaskiy, utaq rimariy, chaymi paykuna huktawan ruranqaku.","Ñawpaqtaqa huk runaq yuyaynin karqan: askha AI programa llank'aykunata huk pachallapi qatinanpaq. Chaymantam chiqap tablero hinaman wiñarqan. Kikiyki machinapin purin, manan cuentata mañakunchu, manataqmi qhatiqniyuqchu. Amigokunapaq hinaspa yachayta munaqkunapaqmi mana qullqiyuq. Manataqmi tukusqachu, chayraykum rakhu kuskankunata hinaspa wakin kutikuna musphayta suyakuy. Chaymi allin, wakin rimariy qallariypaq.","Chiqaptan rimasun. Yuyaykunaqa qanpam kachkan, rurasqakunatapas qanmi qhawanayki. AI-gile ruran chawpipi tukuy imata: kartakunata allin ñiqinpi tiyachin, rimariykita rikuspa allin agenteta rikch'arichin, imataq tikrakusqanta pacha rikuchin, hinaspa llapa chaykunata qanpaq huk pisi t'inkaman tantan. Chay hinapin qan astawan allin yuyaykunapi kakunki, manataq sapa p'unchaw tukuy ruraykunata qatispa sayk'unkichu, sumaqta samarispa."]},{"n":89,"texts":["AI-gile kanmi mana qullqiyuq kanban tablero, chaytan kikiyki computadorpi purichinki. Runakunaq rantinpi, sapa proyectoqa AI agentekunaq huk aylluyuqmi: huk pusaq yuyaykuykikunata kartakunaman hinaspa planman tikran, yanapaqkunataq kartakunata ñawpaqnin kaqmanta hap'inku. Imapas rurasqa kaptin, huk AI yachaqmi yachay ñampikunata qatin hinaspa imatan rikusqanta qanman rikuchin. Chaymanta Qanpaq sutiyuq huk t'inkapi suyan. Qan chaskinki, utaq rimarinki chaymi ayllu huktawan ruran. Qan mana kaspaqa, imapas manan Tukusqamanqa chayanchu. Chhaynatam qan, mana sayk'uspa, tukuy proyectokunata huk qhawaypi riqsinki.","Wakin ruraykuna mana suyasqayki kanman. Tuta qhawaqqa qan puñuptiyki Ruranaykuna columnata hunt'asqa tiyachin, qanpa kutichiyniykita mana munaq kartakunata akllaspa. Huk token yupaqmi rikuchin agentekuna kunan hinaspa kay semanapi hayk'a llamk'asqankuta, Mana Token Modoqa paykunata qullqi usuchiyta sayachinankupaq niyta. Amigokunaman willayta kachayta atinki, hinaspa sapaq willaykunaqa tukuy ladomanta amachasqam. Tableroqa 120 simipi rimanmi, holandés, flamenco, pirata hinaspa klingonmanta qallarispa. Kaykunamanta mana huk qullqipas yanqachu, manataq pipas qanman chayta rantichiyta munanchu. Chaykunaqa huch'uy yanapaykuna, ichaqa sapa p'unchaw llamk'ayta aswan llamp'u ruranku.","AI-gileqa huch'uy sapaq proyectom, manan empresachu. Richqa wakin AI programa proyectokunata qhawariyta munarqan, ichaqa sapa app kichaspa qhawarinanpaq mana munarqanchu. Chayrayku paypas agentekunapas huk tablerota rurarqaku, chaymantataq chay tablerowan wakin partenta kikin rurarqaku. Kunan wichqasqa ñawpaq alfapi kachkan, chaymi huk chhika amigokunapaq, aswan hukkuna, llank'an. Manan chaninkuna p'anqachu kachkan, manan willakuy t'aqachu, nitaq wiñaypaq planchu. Chay allinpaq rikch'akuptinqa, aswan kichakuptin yachayta mañakuyta atinki. Chaywanpas kusikuspa llank'asqayku, hinaspa amigokunaqa kunanpas sapa p'unchaw yanapawanku."]},{"n":144,"texts":["AI-gile kanmi huk runapaq hinaspa askha AI agentekunapaq kanban tablero. Kikiyki computadorpi purin, hinaspa llapanmi mana qullqimanta. Qan proyectokunata yapanki, sapa proyectotaq huk pusaqta hinaspa huch'uy aylluta chaskin. Pusaqwan Discord hina rimanki, hinaspa huk yuyayta willanki; pusaqmi chayta kartakunaman hinaspa planman tikran, chaymanta qan Go ñit'inaykikama suyan. Ayllu kartakunata allin ñiqinpi llank'an, simi modelokunapaq rurasqa llamp'u comando linewan. Imapas qanman kutimunanpaq, huk AI yachaqmi app copiapi ñampikunata qatin hinaspa captura de pantallata hap'in. Tukusqa llank'ayqa t'inkaykiman chayamun, tikrasqa willañiqikunawan hinaspa diffwan. Qan chaskinki, utaq huk rimariyta saqinki, ayllutaq rikch'arispa huktawan ruran. Qanllan huk kartata Tukusqaman apayta atinki. Chhayna, qan kamachiqmi kanki, agentekunataq paciencianwan qanpa munayniykita huntachinku, mana sayk'uspa, mana qhawarisqa. Manan pipas ruranqachu qanta mana arí nichkaptiyki, nitaq imapas pakallapi ruranqachu.","Huk p'unchaw AI-gilewan, aswan pisi hina. Chisiyaqpi wakin rimariykunata saqinki: kay boton mana allin kankunapi kachkan, chay lista ñiqichasqa kanan, tutayaq modo atikunmanchu. Hinaspa puñuq rinki. Agentekuna rimariykunata ñawinchanku, tikraykunata ruranku, yachaykunku hinaspa qanman kutichimunku. Ruranaykuna chusaqyaptin, tuta qhawaqqa backlogmanta kartakunawan chay columnata hunt'achin, chaykunaqa qanpa kutichiyniykita mana munankuchu. Tutamanta huk pisi t'inka tiyan: wakin tapukuykuna hinaspa wakin yachaykunapaq imakuna, sapankaqa puñuyniyuq runapas qatiy atinan ñampikunayuq hinaspa llank'aqta rikuchiq captura de pantallayuq. Qan ñit'ispa riki, allinkunata chaskinki, wakinkunatataq kutichinki. Huk token yupaqmi rikuchin tukuy chaykuna hayk'a usuchisqanta, Mana Token Modotaq pisi semanakunapaq kachkan. Chaymanta ch'isi mikhunaykita mikhunki, chaypiqa agentekuna manaraq yanapayta atinkuchu. Chhaynapi qan samarispa mikhunki, agentekunataq paykunapa ruraykunata qatispa qanpaq wakichinku, tukuy p'unchaw. Chay hinallatan sapa p'unchaw kutimun.","Ñawpaqta, AI-gile mana ima kasqanta willasqayki. Manan startupchu, manan rantinapaqchu, manataqmi pipas willayniykikunata tantanchu. Mana qullqiyuq tablerom, kikiyki computadorpi purin, mana cuentayuq, mana qhatiqyuq, mana cookieyuq. Ima kasqantaq kay: huk allin ñiqichasqa llaqta, tukuy AI programa proyectokunata huk kutilla rikunaykipaq, chaypi agentekunaq aylluqa kartakunata ruran, qantaq kamachikunki. Tupaq kartakunata huñun, chaqruy sutikunata allichan, hinaspa programa hayk'a llamp'u kasqanta qhawan. Pachaq iskay chunka simita rimanmi, holandés hinaspa flamencomanta pirata hinaspa klingonkama. Amigokunaqa sapa hukninku willayta kachayta atinku, sapaqta hinaspa amachasqa. Richwan hinaspa askha pacienciayuq agentekunawanmi rurasqa, aswan kikinmanta llamk'achispa. Wichqasqa ñawpaq alfapin kachkan, chayrayku wakin kuskankunapi rakhu. Kusiq rikch'akuptinqa, sumaqta mañakuy chaymi ñawpaqmanta yaykunki. Chaymi tukuy kay: huk huch'uy, sumaq, mana qullqiyuq yanapaq, qanpa proyectokunata allinta qhawarinanpaq."]}],"quips":{"1":"Huk simi. Callpasapa. Icha aswan callpasapa.","3":"Kimsa simi. Ñawpaqtan aswan chiqap llapa rantina p'anqakunamanta.","8":"Pusaq simi. Stand-upmantapas aswan pisi.","21":"Hatun kaykunaqa story pointskuna, chaynallatan. Arí, imatan.","55":"Phisqa chunka phisqayuq simi. Ñawinchaspayki iskay karta tukukurqan.","144":"Kayqa hatun kaqmi. 233 manan kanchu. Agentekunan puñuq rirqaku."}},"timeline":{"first-idea.name":"Ñawpaq yuyay","first-idea.line":"Ñawpaqpa ñawpaq rimay, manaraq ima programapas kashaqtin.","first-board.name":"Ñawpaq tablero","first-board.line":"Huk tablero kikin ruraynintan qatispa: kartakuna, columnakuna, llamispa saqiy, proyectokuna.","team-roles.name":"Ayllu hinaspa rolkuna","team-roles.line":"Agentekunap perfilninkuna, ayllu plantillakuna, espaciokuna hinaspa pitaq ima ruran.","install.name":"Churay hinaspa lluqsichiy","install.line":"Huk zip amigo churaykuyta atinan, kikin musuqchakuy, canalkuna hinaspa qhepaman kutiy.","usage-saver.name":"Llamk'ay waqaychay","usage-saver.line":"Ruraykuna hayk'a chanin tupuy, programa llamp'u kachun, ruray kamayki waqaychay.","friends.name":"Amigokuna hinaspa rakinakuy","friends.line":"Sapaq DMkuna, pakasqa relay, qayaykuna, rolkuna hinaspa rakisqa proyectokuna.","languages.name":"Simikuna","languages.line":"Sapa pantalla qillqa huk simi willañiqipi, ñawpaqta holandés hinaspa flamenco.","ai-tester.name":"AI yachaq","ai-tester.line":"Huk yachaqmi sapa quykuyta ñawpaqta qhawan hinaspa imatan rikusqanta rikuchin.","website.name":"Web sitio","website.line":"aigile.lol, ñawpaq rikuchina pacha hinaspa kay pacha tupuy.","streaming.name":"Rimay hinaspa streaming","streaming.line":"Discord, Twitch, OBS, streamer modo, GIFkuna hinaspa emojikuna.","no-ai.name":"Mana AIyuq edicion","no-ai.line":"AI mana kaspa programachaqkunapaq huk tablero, hinaspa llapa runaq tablerukuna.","night-watch.name":"Tuta qhawaq","night-watch.line":"Huk qhawaq hinaspa Scrum Master qan puñuptiyki ayllukunata llank'aypi tiyachin.","p-more.name":"Llapa wakin","p-more.line":"Aswan huch'uy yuyaykuna, kuticha suyaspa.","p-android.name":"Celular hinaspa Android","p-android.line":"Tableruykiman celularmanta chayay, chaymanta kikin Android app.","p-release.name":"Alfa hinaspa aswan","p-release.line":"Wichqasqa alfa, kawsaq web sitio, chaymanta beta.","p-languages.name":"Aswan simikuna","p-languages.line":"130 simikuna, yachaqaqkunapaqtaq immersión modo.","p-engines.name":"Aswan AI motorkuna","p-engines.line":"Sapa agentepaq Claude, Codex, Gemini, Copilot utaq Cursor akllay.","p-pro.name":"Llank'ay yachay","p-pro.line":"Manchay rikch'aykuna, merge punkukuna, pantay kartakuna hinaspa amachaykuna.","p-self.name":"Qanta qhawariy","p-self.line":"Sayk'uy modo, kikiyki qhawarispa yuyarichiykuna hinaspa 4:20.","p-servers.name":"Servidorkuna hinaspa hatun kay","p-servers.line":"Llapa pacha servidor churayniykuna, rolkuna hinaspa wiñayta yuyaychay.","p-livestream.name":"Streaming yapaykuna","p-livestream.line":"Twitch rimay, kikin emojikuna hinaspa llapa runaq kawsaq qhawana."},"words":{"button":"📖 Llamk'ay simikuna","h":"📖 Simikuna sut'inchasqa","intro":"AI-gile nisqapi tarisqayki simikuna, sut'i rimaypi: ruray, mana manchakuspa tikray, llamk'achiqkunapaq purichkananpaq waqaychay, AI-wan ayllu hina llamk'aypas.","search":"Simita maskay…","none":"Mana simi tupanchu.","close":"Wichqay","count":{"one":"{count} simi","other":"{count} simi"},"groups":[{"id":"build","name":"🛠️ Ruray"},{"id":"change","name":"🔀 Allinta tikray"},{"id":"run","name":"🛎️ Huk serviciota purichiy"},{"id":"team","name":"🤝 Ayllu hina llamk'ay (AI-wanpas)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Proyectop code folderninpas, commitkunap hunt'a willayninpas, sapa kuti GitHubpi waqaychasqa.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Codepi t'aqa llamk'ay ñan, tikraykuna ruranapaq hatun versionta mana llamiy.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Codep waqaychasqa rikch'aynin, imachus tikrakurqan pisi willaywan. Sapa kuti chayman kutiyta atinki.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Waqaychasqa rikch'aykunata (commits) kay computadoramanta GitHubman apachiy, backup hinaspa rakisqa kananpaq."},{"id":"merge","g":"build","word":"Merge","text":"Branchpa tikrayninkunata hatun versionman hukllachay."},{"id":"pr","g":"build","word":"Pull request","text":"Branchpa tikraykunata qhawasqa hinaspa hatun versionman tinkichisqa kananpaq mañakuy.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Codeta allichay, imachus ruranan mana tikraspa: aswan huch'uy willañiqikuna, aswan sut'i sutikuna, pisi kutipay."},{"id":"bug","g":"build","word":"Bug","text":"Imachus ruranan hinaqa mana ruraq.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Tukusqa llamk'ayta pruebay, mañasqa hina ruraptinchus qhawanapaq, chaskinaykiman.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Quality assurance nisqamanta: imapas manaraq kawsayman richkaptin kikinmanta purichkaq qhawaykuna. QA puka kaptinqa imapas pantan, manataq kawsayman riyta atinchu allichakunankama.","also":["allin kayta qhaway","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Musuq versionta kausaypi churay, ej. servidorpi runakuna llamk'achinankupaq."},{"id":"release","g":"change","word":"Release","text":"Tukusqa llamk'aykunamanta sutiyuq huñu, kuskalla kawsayman rin, ima tikrasqanmanta pisi willakuykunawan. 🚀 Releasekuna tukusqa kartakunamanta willakuykunata qillqan.","also":["releasekuna","lanzamiento"]},{"id":"rollback","g":"change","word":"Rollback","text":"Musuq version sasachakuyta apamuptin, qhipa allin llamk'aq versionman kutiy. AI-gile-pi sapa tikraypi qillqasqa kutichiy ruraykunamanta huk checklistta ruran.","also":["kutichiy","ñawpaq versionman kutiy","roll back"]},{"id":"live","g":"change","word":"Kawsaypi","text":"Runakuna cheqaqta llamk'achisqanku version, mana imakunata pruebanapaq copia hinachu. Programadorkunaqa production nispapas sutichanku.","also":["live","production","producción"],"noTip":1},{"id":"change","g":"change","word":"Tikray","text":"Runakuna hap'ipakusqanku imapi yuyaychasqa tikray, ñawpaqta qillqasqa: ima, imarayku, riesgo, hayk'aq, imaynata kutichina. 🔀 Tikrayta mañakuy nisqawan qallariy.","also":["tikraykuna","tikray mañakuy","change request"],"noTip":1},{"id":"risk","g":"change","word":"Riesgo","text":"Mana allinman tukunman chay, yupasqa: hayk'a atikunman, hayk'a mana allin kanman. ⚠️ Riesgokuna huk listallapi waqaychan, aswan hatun yupayniyuq ñawpaqta, sapakamataq kaqmanta qhawanapaq p'unchawniyuq.","also":["riesgokuna","riesgo qillqa"]},{"id":"chgwin","g":"change","word":"Tikray p'unku","text":"Tikraykuna kawsayman riyta atinanku pachakuna, ahinataq upalla martes ch'isi. P'unkumanta hawapiqa tikray kartaqa mana tukuchikuyta atinchu, emergencia kaptinlla.","also":["tikray p'unkukuna","change window"]},{"id":"gonogo","g":"change","word":"Rishun / ama rinchu","text":"Huk tikray kawsayman manaraq richkaptin utqay akllanakuy: aprobanan sapa runa Rishun utaq Ama rinchu nin. Llapanku kuska kaptinlla rin.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Aprobay","text":"Llamk'ay manaraq qallarichkaptin huk ari nisqata suyay. Masiyki churasqan kartapas, tikraypas ✅ Aprobasqa nisqapi suyan, aprobanaykikama utaq mana ninaykikama.","also":["aprobasqa","aprobación"]},{"id":"quiettime","g":"change","word":"Upalla pacha","text":"Huk pacha, ahinataq stream, demo utaq tuta, mana imapas kawsayman rinchu. Ayllukunaqa llamk'aspa pruebaspa kachkanku, ichaqa kawsayman riyqa tukunankama suyan. Huk cheqaskunapiqa change freeze nispa sutichanku.","also":["upalla pachakuna","change freeze"]},{"id":"service","g":"run","word":"Servicio","text":"Qan rurasqayki, runakunataq hap'ipakunku, ahinataq huk web p'anqa utaq app, qhawasqa purichkananpaq. “Kay proyecto huk serviciom” nisqata akllay, hinaspa willay ima qun, pikuna llamk'achin, pitaq guardiapi kachkan.","also":["serviciokuna"]},{"id":"uptime","g":"run","word":"Uptime qhaway","text":"Sapa iskay kimsa minutupi kikinmanta qhaway, serviciuyki kutichichkanraqchu. Achkha kuti qatiqninpi pantaptinqa, AI-gile kikinmanta huk incidente kartata kichan.","also":["uptime","kawsay qhaway"]},{"id":"statuspage","g":"run","word":"Status p'anqa","text":"Llapanpaq kichasqa p'anqa: servicio llamk'achkanchu (q'umir, naranja utaq puka) chayta qhawachin, qhipa willakuywan, chhaynapi llamk'achiqkuna kikinku qhawanankupaq, mana tapuspa.","also":["status page","status p'anqakuna"]},{"id":"desk","g":"run","word":"Servicio escritorio","text":"Serviciokita llamk'achiq runakunap tapukuyninkuna willakuyninkuna chayamunan. AI-gile sapakamata mañakuyman, pantayman utaq yuyayman t'aqan, hinaspa ninmi ñas willasqa kaqman rikch'akuptin.","also":["servicio escritoriokuna","escritorio","service desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Servicio mañakuy","text":"Pipas sapa p'unchaw kaqta mañan, ahinataq musuq cuentata utaq pisi yanapayta, imapas p'akisqa kasqanta willanan rantinpi. Muyunanta suyan; pantayqa ñawpaqta rin.","also":["servicio mañakuykuna","mañakuy"]},{"id":"incident","g":"run","word":"Incidente","text":"Kunan pacha llamk'achiqkunapaq p'akisqa, ahinataq web p'anqa urmasqa. 🔥 Incidente kartaqa llapan suyaqkunata ñawpan: kaqmanta llamk'achiyqa ñawpaqta.","also":["incidentekuna"]},{"id":"major","g":"run","word":"Hatun pantay","text":"Hatun pantayqa hatun incidente: achkha runakuna ñak'arisqa, utaq qullqi utaq datokuna peligropi. Huk botonlla llapan ayllukunata churan (swarm), guardiapi kaqta rikch'arichin, sapa 30 minutupi estado willakuyta mañan.","also":["hatun incidente","major incident"]},{"id":"oncall","g":"run","word":"Guardiapi","text":"Imapas p'akikuptin kutichiq kay, tutapas. Sapa serviciopa guardiapi huk ayllu masin kan, paytam ñawpaqta rikch'arichinku incidentenkunapaq.","also":["guardia","on call","on-call"]},{"id":"replyby","g":"run","word":"Kutichiy tiempo","text":"Huk karta hayk'a pachata ñawpaq kutichiyta suyanman, ahinataq huk hora incidentepaq. Chaymantaqa puka relojta chaskin, mana imapas upallalla qunqasqa kananpaq. Response target nispapas sutichanku.","also":["kutichiy tiempokuna","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Incidente qhipata pisi qhipaman qhaway: ima pasarqan, ima yanaparqan, imata tikrana, mana pitapas huchachaspa. Mana post-mortemniyuqqa incidente mana wisq'akuyta atinchu.","also":["post-mortems","postmortem","incidente qhipa qhaway"]},{"id":"problem","g":"run","word":"Sasachakuy","text":"Huk utaq achkha incidentekunapa pakasqa imaraykun. 🧩 Sasachakuy kartaqa kutimpuchkaq incidentekunata huñun, imaraykunta tarispa wiñaypaq allichanapaq.","also":["sasachakuykuna","problema"],"noTip":1},{"id":"rootcause","g":"run","word":"Saphi imarayku","text":"Imapas p'akikusqanpa cheqaq imaraykun, mana rikusqayki mana allin rinallanchu. Saphi imaraykuta allichay, incidentetaq manaña kutimunchu.","also":["saphi imaraykukuna","root cause"]},{"id":"workaround","g":"run","word":"Pachapaq ñan","text":"Cheqaq allichay wakichisqa kanankama imakunata llamk'achkachinapaq ñan, ahinataq imapas hark'akuptin kaqmanta qallarichiy. Sasachakuy kartapi qillqasqa, mana pipas kaqmanta yuyaykunanpaq.","also":["allichakunankama pachapaq","workaround"]},{"id":"knownerror","g":"run","word":"Riqsisqa pantay","text":"Imaraykun yachasqaña, pachapaq ñanniyuq sasachakuy, ichaqa manaraq allichasqa. 🧩 Riqsisqa pantaykuna paykunata listapi qhawachin, llapanku pachapaq ñanta llamk'achinankupaq, mana kaqmanta aspispa.","also":["riqsisqa pantaykuna","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Riqsisqa sasachakuyta allichanapaq sapa ruraymanta yachachiykuna, sapa kuti kaqllata utqaylla ruranapaq. Hatun incidente qhipata ayllu huk runbookta yuyaychanman, qantaq OK ninki.","also":["runbookkuna"]},{"id":"ci","g":"run","word":"Churay elemento","text":"Serviciokiq hapipakusqan huk kaq, ahinataq servidor, dominio, certificado, clave utaq qatuq. 🗂️ Churay elementokuna sapa serviciopaq listapi rikuchin, chhaynapi rikunki ima kaqkunatam pantay waqtan, imataq musuqyachinan utaq backup ruwanan.","also":["churay elementokuna","elementokuna"]},{"id":"expiry","g":"run","word":"Tukukuy p'unchaw","text":"AI-gile p'unchawkunata qhawan, ahinataq certificado utaq dominio tukukunan p'unchawta. Chay p'unchawmanta 30 p'unchaw ñawpaqta huk kartata ruran musuqyachinapaq, chhaynapi mana imapas mana yachasqalla sayankunchu.","also":["tukukuy p'unchawkuna","tukukuy","tukukuy qhaway"]},{"id":"backup","g":"run","word":"Backup","text":"Ñawpaqmanta datoykikunapa waqaychasqa copian, imapas chinkaptin utaq waqlliptin kutinapaq. AI-gile sapa p'unchaw tablaykikunapa backupninta ruran.","also":["backupkuna","back-up"]},{"id":"restore","g":"run","word":"Kutichimuy","text":"Backupmanta datokunata kutichimuy. Huk backupqa kutichimuy atikusqanta yachaptiykillam cheqaqta valen, chayrayku sapa kutilla pruebay.","also":["kutichimusqa","restore"]},{"id":"svcreview","g":"run","word":"Servicio qhawanay","text":"Huk serviciopa huk killanta qhipaman qhawariy: kichasqa allichasqa pantaykuna, runakuna hayk'a utqaylla kutichiyta chaskirqanku, uptime, llamk'achisqa tokenkuna ima. Killa qhawanay sapa serviciopaq rikuchin.","also":["servicio qhawanaykuna","killa qhawanay","killa qhawanaykuna"]},{"id":"accessreview","g":"run","word":"Yaykuy qhawanay","text":"Sapa 90 p'unchaw pitaq yaykuyta atinraq chayta qhaway: rakinakuy tinkikuna, masikunap ruraynin, waqaychasqa secretokuna. Sapakamata waqaychanki utaq qarqunki, chhaynapi mawk'a yaykuykuna mana qhepakunchu.","also":["yaykuy qhawanaykuna"]},{"id":"improvements","g":"run","word":"Allichay lista","text":"Aylluq aswan allin ruranapaq yuyaychasqan llapan, huk k'itillapi: retro yuyaychaykuna, qhawanay ruraykuna, sasachakuy allichaykuna, sapakamaq estadonwan. 📈 Allichaykuna ukhupi tarinki.","also":["allichay listakuna","allichaykuna"]},{"id":"tokencap","g":"run","word":"Token tope","text":"Huk serviciopa agentenkuna llamk'achinanku tokenkunapaq killa tope. 80%-pi willakuyta chaskinki; 100%-pi paykunap pakasqa llamk'aynin hamuq killakama suyan, utaq topeta wicharichinaykikama.","also":["token topekuna","killa token tope"]},{"id":"backlog","g":"team","word":"Backlog","text":"Yuyaykuna hinaspa manaraq yuyaychasqa ruranakuna. Chaypi mana imapas ruwakunchu Ruranaykuna kaqman rinankama."},{"id":"sprint","g":"team","word":"Sprint","text":"Pisi llamk'ay pacha (sapa kuti huk utaq iskay simana) tukunapaq kartakunawan.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Pisi tapukuy: sapa ayllu masi imata rurarqan, imata qatiqninpi ruranqa, imataq hark'an.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Columnakunayuq tablero (Ruranaykuna, Ruraypi, Tukusqa), chaypi kartakuna lluq'imanta pañaman purinku llamk'ay puriptin."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: huk columna aswan hayk'a kartakunata hap'inan, ayllu aswan qallariymanta ñawpaqta tukunanpaq.","also":["WIP"]},{"id":"dod","g":"team","word":"Tukusqa ima ninan","text":"Ayllupa pisi checklistnin, “tukusqa” ima ninan, ahinataq pruebasqa hinaspa sut'inchasqa, manaraq karta qanman chayachkaptin. Paypa masin, Wakichisqa ima ninan, willan hayk'aq karta qallarinapaq sut'iña kasqanta.","also":["Definition of Done","Definition of Ready","Wakichisqa ima ninan"]},{"id":"testpile","g":"team","word":"Test huñu","text":"Pruebanaykipaq suyachkaq tukusqa kartakuna, huknin hukninpa qhipanta. Hukta chaskiy utaq willakuywan kutichiy, qatiqtaq rikhurimun.","also":["test huñukuna","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Ayllu imayna llamk'asqanta qhipaman qhaway, huk aswan allin ruranata rimanakunapaq. AI-gile-pi retroqa ayllupa llamk'ay ñanninpi huk tikrayta yuyaychan, qantaq Go utaq Manaraq ninki.","also":["qhawarispa","retrospectiva"]},{"id":"peerreview","g":"team","word":"Masi qhawanay","text":"Iskay kaq ñawikuna: huk AI sapa kartapa llamk'ayninta qhawan qanman manaraq chayachkaptin, chhaynapi aswan pisi pantaykuna pasan.","also":["peer review","code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Llapanku makiwan: sapa ayllu huk llamk'aykunata saqespa huk usqhay proyectota yanapan allichakunankama. Huk proyectokunaqa chaykama suyanku.","also":["huñuy","enjambre","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Llamk'ay purichkananpaq qhawaq: hark'asqa kartakunata rikun, ayllukunata kallpachan, ima suyachkasqantataq yuyarichisunki. AI-gile-pi Lead Scrum Master kayta llapan proyectokunapi ruran.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agente","text":"Kikin huk rurayta llamk'aq AI: codeta ñawinchan, tikrayta ruran, qhawaykunata purichin, willakun.","also":["agentes"]},{"id":"token","g":"team","word":"Token","text":"AI llamk'achiy yupana unidad: ñawinchasqa utaq qillqasqa yaqa iskay kimsa qillqakuna. Pisi token, aswan plan puchun.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Pisi kamachiy, takyasqa pachapi kikinmanta purin, ej. AI sesión qallarishaqtin, ayllu willaykunata uyarinanpaq.","also":["hooks"]}]}};
